// Dispatch brain: session window, supplier ranking, acceptance locking.
// State lives in workflow static data so it survives an n8n restart.
const store = $getWorkflowStaticData('global');
store.jobs = store.jobs || {};
store.offers = store.offers || [];
store.inbound = store.inbound || {};

const DAY = 24 * 60 * 60 * 1000;
const OFFER_TIMEOUT_MS = 5 * 60 * 1000;
const now = Date.now();

// Suppliers would normally come from a Google Sheet. Kept inline so the
// workflow runs before the Sheet credential exists.
const SUPPLIERS = [
  // Demo supplier points at the number registered on the Meta test number,
  // so the outbound leg is observable. Real deployments read this from a sheet.
  { id: 'sup-1', name: 'Highway Tyres', phone: '<RECIPIENT_MSISDN>', km: 8.2 },
  { id: 'sup-2', name: 'N1 Truck Assist', phone: '27820001002', km: 14.7 },
  { id: 'sup-3', name: 'Midrand Fitment', phone: '27820001003', km: 31.5 },
];

const body = $input.first().json.body || $input.first().json;
const value = body?.entry?.[0]?.changes?.[0]?.value;
const message = value?.messages?.[0];

if (!message) {
  return [{ json: { action: 'ignore', reason: 'no message in payload' } }];
}

const from = message.from;
const text = (message.text?.body || '').trim();
store.inbound[from] = now;                       // opens this contact's 24h window

// A supplier replying YES <reference> accepts the job.
const accept = text.match(/^\s*(yes|ya|accept|ambil)\s+(\S+)/i);
if (accept) {
  const reference = accept[2].toUpperCase();
  const job = Object.values(store.jobs).find(j => j.reference === reference);
  const supplier = SUPPLIERS.find(s => s.phone === from);

  if (!job) {
    return [{ json: { action: 'reply', to: from, windowOpen: true,
                      text: `No open job found for ${reference}.` } }];
  }
  if (job.assignedSupplierId) {
    // First acceptance already won. This is the idempotent branch.
    const already = job.assignedSupplierId === supplier?.id;
    return [{ json: { action: 'reply', to: from, windowOpen: true, jobId: job.id,
                      outcome: already ? 'assigned' : 'already_assigned',
                      text: already
                        ? 'You already have this job. Please send an ETA.'
                        : 'This job is already assigned to another supplier. No action needed.' } }];
  }

  job.assignedSupplierId = supplier?.id || from;
  job.status = 'assigned';
  job.assignedAt = now;
  store.offers.forEach(o => { if (o.jobId === job.id) o.resolved = true; });

  return [{ json: { action: 'assign', to: from, windowOpen: true, jobId: job.id,
                    reference: job.reference, outcome: 'assigned',
                    text: 'Job assigned to you. Please proceed and send an ETA.',
                    clientPhone: job.clientPhone } }];
}

// Anything else from a new contact is treated as a breakdown report.
const reference = 'JOB' + String(Object.keys(store.jobs).length + 1).padStart(4, '0');
const job = {
  id: reference, reference, detail: text, clientPhone: from,
  status: 'pending', createdAt: now, triedSupplierIds: [], assignedSupplierId: null,
};
store.jobs[reference] = job;

const nextSupplier = SUPPLIERS[0];
job.triedSupplierIds.push(nextSupplier.id);
job.status = 'offered';
store.offers.push({ jobId: job.id, supplierId: nextSupplier.id,
                    expiresAt: now + OFFER_TIMEOUT_MS, resolved: false });

// Window check decides free-form vs approved template for the supplier message.
const supplierLastInbound = store.inbound[nextSupplier.phone] || 0;
const supplierWindowOpen = (now - supplierLastInbound) <= DAY;

return [{
  json: {
    action: 'dispatch',
    jobId: job.id,
    reference,
    detail: text,
    clientPhone: from,
    clientWindowOpen: true,
    supplier: nextSupplier,
    supplierWindowOpen,
    supplierMessageType: supplierWindowOpen ? 'text' : 'template',
    clientText: `Got it. Reference ${reference}. Finding the closest fitment now.`,
  },
}];

// Meta webhook verification handshake.
// Echo hub.challenge back verbatim, but only when the verify token matches.
//
// The token is a constant rather than $env because n8n ships
// N8N_BLOCK_ENV_ACCESS_IN_NODE=true, which denies $env inside Code nodes.
// This value only proves the endpoint is ours during Meta's one-time
// handshake. It grants no access to anything.
const EXPECTED = 'SET_YOUR_OWN_VERIFY_TOKEN';

const query = $input.first().json.query || {};

if (query['hub.mode'] === 'subscribe' && query['hub.verify_token'] === EXPECTED) {
  return [{ json: { ok: true, challenge: query['hub.challenge'] } }];
}
return [{ json: { ok: false, challenge: 'verification failed' } }];

// Break each message into fields, then append it to a durable log.
// Mirrors dispatch/extract.py, which carries the unit tests for this logic.
//
// A field the message does not state stays null. An empty cell is a question
// somebody can answer; a guessed plate sends a truck to the wrong place.
const store = $getWorkflowStaticData('global');
store.log = store.log || [];
// One-time cleanup: drop entries recorded before extraction existed.
if (!store.migratedV2) { store.log = store.log.filter(e => e.completeness !== undefined); store.migratedV2 = true; }

const d = $input.first().json;
if (d.action === 'ignore') {
  return [{ json: { recorded: false, reason: d.reason || 'nothing to record' } }];
}

const raw = d.detail || d.text || '';
const text = raw.toLowerCase();

const firstMatch = (pats) => {
  for (const p of pats) { const m = text.match(p); if (m) return m; }
  return null;
};

const FAULTS = [
  ['tyre',    [/\bban\b/, /\btyre\b/, /\btire\b/, /\bbocor\b/, /\bblown\b/, /\bflat\b/, /\bkempes\b/]],
  ['battery', [/\baki\b/, /\bbattery\b/, /\bsoak\b/, /\bstarter\b/]],
  ['engine',  [/\bmesin\b/, /\bengine\b/, /\boverheat\b/, /\bmogok\b/]],
  ['fuel',    [/\bbensin\b/, /\bsolar\b/, /\bfuel\b/, /\bdiesel\b/]],
  ['brake',   [/\brem\b/, /\bbrake\b/, /\bblong\b/]],
];
const POSITIONS = [
  ['front', [/\bdepan\b/, /\bfront\b/]],
  ['rear',  [/\bbelakang\b/, /\brear\b/, /\bback\b/]],
];

let faultType = null;
for (const [name, pats] of FAULTS) { if (firstMatch(pats)) { faultType = name; break; } }
let position = null;
for (const [name, pats] of POSITIONS) { if (firstMatch(pats)) { position = name; break; } }

// Plates are read from original casing. Road codes such as N1 are excluded.
let plate = null;
for (const p of [/\b([A-Z]{1,2}\s?\d{1,4}\s?[A-Z]{1,3})\b/g, /\b([A-Z]{2}\d{4,6})\b/g]) {
  const found = raw.match(p);
  if (found) {
    for (const c of found) {
      const clean = c.replace(/\s+/g, '').toUpperCase();
      if (/^(N\d|M\d|KM|TOL|JL)$/.test(clean)) continue;
      if (/\d/.test(clean) && /[A-Z]/.test(clean)) { plate = clean; break; }
    }
  }
  if (plate) break;
}

let km = null;
const kmMatch = text.match(/\bkm\.?\s*(\d+(?:[.,]\d+)?)/) || text.match(/\b(\d+(?:[.,]\d+)?)\s*km\b/);
if (kmMatch) { const v = parseFloat(kmMatch[1].replace(',', '.')); if (!isNaN(v)) km = v; }

let road = null;
const roadMatch = firstMatch([
  /\b(tol\s+[a-z]+(?:\s+[a-z]+)?)\b/, /\b(jalan\s+[a-z]+(?:\s+[a-z]+)?)\b/,
  /\b(jl\.?\s+[a-z]+(?:\s+[a-z]+)?)\b/, /\b([nm]\d\s+(?:north|south|east|west))\b/, /\b([nm]\d)\b/,
]);
if (roadMatch) {
  road = roadMatch[1].replace(/\s+/g, ' ').replace(/\s+km$/i, '').trim()
    .replace(/\b\w/g, c => c.toUpperCase());
}

// Marker list mirrors dispatch/extract.py. Keep both in step: an earlier
// version omitted "jalan" here and misread Indonesian messages as English.
const idHits = [/\bpecah\b/, /\bban\b/, /\btol\b/, /\bbelakang\b/, /\bdepan\b/, /\bbocor\b/,
                /\bmogok\b/, /\baki\b/, /\bjalan\b/, /\brusak\b/, /\bbantuan\b/,
                /\btolong\b/, /\bkendaraan\b/].filter(p => p.test(text)).length;
const enHits = [/\bblown\b/, /\btyre\b/, /\bfront\b/, /\brear\b/, /\bnorth\b/, /\bhelp\b/,
                /\btruck\b/, /\bflat\b/].filter(p => p.test(text)).length;
const language = (idHits === 0 && enHits === 0) ? null : (idHits >= enHits ? 'id' : 'en');

const completeness = [plate, faultType, position, road, km].filter(v => v !== null).length;

const entry = {
  at: new Date().toISOString(),
  reference: d.reference || d.jobId || '-',
  from: d.clientPhone || d.to || '-',
  plate, faultType, position, road, km, language, completeness,
  supplier: (d.supplier && d.supplier.name) || null,
  distanceKm: (d.supplier && d.supplier.km) !== undefined ? d.supplier.km : null,
  channel: d.supplierMessageType || null,
  rawText: raw,
};

store.log.unshift(entry);
store.log = store.log.slice(0, 200);

return [{ json: { recorded: true, total: store.log.length, entry } }];

// Render the structured log. Supports ?format=csv and ?format=json so the same
// data can leave as a spreadsheet or feed another system.
const store = $getWorkflowStaticData('global');
const log = store.log || [];
const q = $input.first().json.query || {};
const format = (q.format || 'html').toLowerCase();

const mask = (p) => {
  const s = String(p || '-');
  return s.length > 6 ? s.slice(0, 4) + '*'.repeat(s.length - 6) + s.slice(-2) : s;
};

const COLS = ['at','reference','from','plate','faultType','position','road','km','language','completeness'];

if (format === 'csv') {
  const esc = (v) => {
    const s = v === null || v === undefined ? '' : String(v);
    return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
  };
  const rows = log.map(e => COLS.map(c => esc(c === 'from' ? mask(e[c]) : e[c])).join(','));
  return [{ json: { body: [COLS.join(','), ...rows].join('\n'),
                    contentType: 'text/csv; charset=utf-8' } }];
}

if (format === 'json') {
  const clean = log.map(e => { const o = {}; COLS.forEach(c => o[c] = c === 'from' ? mask(e[c]) : e[c]); return o; });
  return [{ json: { body: JSON.stringify({ count: clean.length, jobs: clean }, null, 2),
                    contentType: 'application/json; charset=utf-8' } }];
}

const esc = (v) => String(v === null || v === undefined ? '' : v)
  .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const cell = (v) => v === null || v === undefined
  ? '<td class="na">not stated</td>' : `<td>${esc(v)}</td>`;

// Summary counts, computed from the data rather than typed in.
const faults = {};
log.forEach(e => { const k = e.faultType || 'unclassified'; faults[k] = (faults[k]||0)+1; });
const byFault = Object.entries(faults).sort((a,b) => b[1]-a[1]);
const withKm = log.filter(e => e.km !== null);
const avgComplete = log.length
  ? (log.reduce((s,e) => s + (e.completeness||0), 0) / log.length).toFixed(1) : '0';

const rows = log.map(e => `<tr>
  <td class="dim">${esc(e.at.replace('T',' ').slice(0,19))}</td>
  <td class="ref">${esc(e.reference)}</td>
  <td class="dim">${esc(mask(e.from))}</td>
  ${cell(e.plate)}
  <td>${e.faultType ? `<span class="tag f-${esc(e.faultType)}">${esc(e.faultType)}</span>` : '<span class="na">not stated</span>'}</td>
  ${cell(e.position)}
  ${cell(e.road)}
  ${(e.km === null || e.km === undefined) ? '<td class="na">not stated</td>' : `<td>km ${esc(e.km)}</td>`}
  <td class="dim">${esc(e.language || '')}</td>
  <td>${e.completeness === undefined || e.completeness === null ? '<span class="na">n/a</span>' : `<span class="score s${e.completeness}">${esc(e.completeness)}/5</span>`}</td>
</tr>`).join('');

const html = `<!doctype html>
<html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Roadside dispatch report</title>
<style>
 body{font:14px/1.55 -apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;
      margin:0;padding:30px;background:#0f1115;color:#e7e9ee}
 h1{font-size:19px;margin:0 0 3px} p.sub{color:#8b93a7;margin:0 0 20px;font-size:13px}
 .cards{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:20px}
 .card{background:#161a23;border:1px solid #252c3b;border-radius:8px;padding:10px 14px;min-width:104px}
 .card b{display:block;font-size:20px;font-weight:600} .card span{color:#8b93a7;font-size:11px}
 table{border-collapse:collapse;width:100%;font-size:12.5px}
 th{text-align:left;color:#8b93a7;font-weight:500;padding:8px 9px;border-bottom:1px solid #2a3142;white-space:nowrap}
 td{padding:8px 9px;border-bottom:1px solid #1b2030;vertical-align:top}
 .dim{color:#8b93a7} .na{color:#555c6e;font-style:italic}
 .ref{font-family:ui-monospace,Menlo,monospace;color:#7cc4ff}
 .tag{border-radius:4px;padding:2px 7px;font-size:11px}
 .f-tyre{background:#3a2a12;color:#f0b66b} .f-battery{background:#2a1c3a;color:#c49bf0}
 .f-engine{background:#3a1c1c;color:#f09b9b} .f-fuel{background:#1c2a3a;color:#9bc4f0}
 .f-brake{background:#3a1c2a;color:#f09bc4}
 .score{font-family:ui-monospace,Menlo,monospace;font-size:11px;padding:2px 6px;border-radius:4px}
 .s5{background:#142c1c;color:#79d39a} .s4{background:#142c1c;color:#79d39a}
 .s3{background:#3a2a12;color:#f0b66b} .s2{background:#3a2a12;color:#f0b66b}
 .s1{background:#3a1c1c;color:#f09b9b} .s0{background:#3a1c1c;color:#f09b9b}
 .links{margin-top:18px;font-size:12px} .links a{color:#7cc4ff;margin-right:14px}
 .empty{color:#8b93a7;padding:26px 0}
</style></head><body>
<h1>Roadside dispatch report</h1>
<p class="sub">Fields parsed by n8n from WhatsApp Cloud API messages.</p>
<div class="cards">
  <div class="card"><b>${log.length}</b><span>jobs</span></div>
  <div class="card"><b>${withKm.length}</b><span>with location</span></div>
  <div class="card"><b>${avgComplete}</b><span>avg fields /5</span></div>
  ${byFault.slice(0,3).map(([k,v]) => `<div class="card"><b>${v}</b><span>${esc(k)}</span></div>`).join('')}
</div>
${log.length ? `<table><thead><tr>
<th>Received</th><th>Reference</th><th>From</th><th>Plate</th><th>Fault</th>
<th>Position</th><th>Road</th><th>Marker</th><th>Lang</th><th>Fields</th>
</tr></thead><tbody>${rows}</tbody></table>`
: '<div class="empty">No jobs recorded yet. Send a WhatsApp message to create one.</div>'}
<div class="links">
  <a href="?format=csv">Download CSV</a>
  <a href="?format=json">JSON</a>
</div>
</body></html>`;

return [{ json: { body: html, contentType: 'text/html; charset=utf-8' } }];
